**When to use:** Search operations, filtering, finding specific nodes.

### Pattern 3: Operation + Result

Performs an operation and reports a summary:

```jac
node Item {
    has name: str;
}

walker:priv CreateItem {
    has name: str,
        reports: list[Item] = [];   # the created Item flows back typed

    can create with Root entry {
        new_item = here ++> Item(name=self.name);
        report new_item;  # Report the created item
    }
}

with entry {
    # Usage
    result = root spawn CreateItem(name="New Item");
    created: Item = result.reports[0];  # hydrated as Item on the client
}
```

**When to use:** Create, update, delete operations.

### Pattern 4: Nested Walker Spawning

When one walker spawns another, use `has` attributes to pass data between them instead of relying on `reports`:

```jac
walker:priv InnerWalker {
    has result: str = "";

    can work with Root entry {
        self.result = "inner data";
    }
}

walker:priv OuterWalker {
    can work with Root entry {
        # Spawn inner walker
        inner = InnerWalker();
        root spawn inner;

        # Access inner walker's data via its attributes
        report {"outer": "data", "inner": inner.result};
    }
}

with entry {
    # Usage
    result = root spawn OuterWalker();
    # result.reports[0] = {"outer": "data", "inner": "inner data"}
}
```

**Important:** When spawning walkers from within other walkers, the inner walker's `reports` list may not be accessible from the parent context. Use `has` attributes on the inner walker to communicate results back to the outer walker.

### Pattern 5: Multiple Reports (Complex Operations)

Some operations naturally produce multiple reports:

```jac
def do_processing(input: str) -> list {
    return [input, input + "_processed"];
}

walker:priv ProcessAndSummarize {
    has input: str;

    can process with Root entry {
        # First report: raw results
        results = do_processing(self.input);
        report results;

        # Second report: summary
        report {
            "count": len(results),
            "status": "complete"
        };
    }
}

with entry {
    # Usage
    result = root spawn ProcessAndSummarize(input="data");
    raw_results = result.reports[0];  # First report
    summary = result.reports[1];       # Second report
}
```

**When to use:** Operations that produce both detailed results and summaries.

## Safe Access Patterns

Always handle the possibility of empty reports:

```jac
walker:priv MyWalker {
    can work with Root entry {
        report "data";
    }
}

def process(item: any) {
    print(item);
}

with entry {
    # Safe single report access
    result = root spawn MyWalker();
    data = result.reports[0] if result.reports else None;

    # Safe with default value
    data = result.reports[0] if result.reports else [];

    # Check length for multiple reports
    if result.reports and len(result.reports) > 1 {
        first = result.reports[0];
        second = result.reports[1];
    }

    # Iterate all reports
    for item in (result.reports if result.reports else []) {
        process(item);
    }
}
```

## Response Object Structure

The full response object from `root spawn Walker()`:

```jac
walker:priv MyWalker {
    can work with Root entry {
        report "result";
    }
}

with entry {
    response = root spawn MyWalker();

    # Available properties
    print(response.reports);    # Array of all reported values
}
```

## Best Practices

1. **Always declare `has reports: list[T]`** - The default `list[any]` propagates `any` into consumer code, and Jac's strict gradual-typing rule rejects `any` flowing into typed destinations. Typing the report channel at the walker is almost always cheaper than annotating every receiving local as `any` and narrowing back. See [The `any` Type and Gradual Typing](foundation.md#the-any-type-and-gradual-typing).
2. **Prefer single reports** - Accumulate data and report once at the end
3. **Use `with Root exit`** - Best place for final reports after traversal
4. **Report typed objects directly** - Return node/obj instances instead of manually constructing dicts. The runtime automatically serializes typed objects with field metadata, and client code receives them as hydrated typed instances with proper field access (e.g., `task.title` instead of `task["title"]`)
5. **Always check `.reports`** - It may be empty or undefined
6. **Use typed return annotations** - For `def:pub` functions, annotate with `-> Task` or `-> list[Task]` instead of `-> dict` or `-> list` to enable automatic type hydration on the client

### Don't: Manually construct dicts from typed objects

```jac
# Bad: Manual dict construction loses type information
walker:priv BadCreate {
    has name: str;

    can create with Root entry {
        item = here ++> Item(name=self.name);
        report {"name": item.name, "data": item.data};  # Don't do this
    }
}

# Good: Report the typed object directly
walker:priv GoodCreate {
    has name: str;

    can create with Root entry {
        item = here ++> Item(name=self.name);
        report item;  # The runtime handles serialization automatically
    }
}
```

The same applies to `def:pub` functions -- return typed objects instead of manually constructed dicts:

```jac
# Bad: Manual dict return
def:pub get_task(id: str) -> dict {
    task = find_task(id);
    return {"id": jid(task), "title": task.title, "done": task.done};
}

# Good: Typed return -- client receives a hydrated Task instance
def:pub get_task(id: str) -> Task {
    return find_task(id);
}
```

### Don't: Report in a loop without accumulation

```jac
node Item {
    has data: str;
}

# Bad: Creates many small reports
walker:priv BadPattern {
    can process with Item entry {
        report here.data;  # N reports for N items
    }
}

# Good: Accumulate and report once
walker:priv GoodPattern {
    has items: list = [];

    can start with Root entry {
        visit [-->];
    }

    can process with Item entry {
        self.items.append(here.data);
    }

    can finish with Root exit {
        report self.items;  # One report with all items
    }
}
```

### Don't: Assume report order without documentation

```jac
walker:priv MyWalker {
    can work with Root entry {
        report ["item1", "item2"];
        report {"count": 2};
    }
}

with entry {
    result = root spawn MyWalker();

    # Bad: Magic indices
    data = result.reports[0];
    meta = result.reports[1];

    # Good: Document or structure clearly
    # reports[0]: List of items
    # reports[1]: Metadata object
    data = result.reports[0] if result.reports else [];
    meta = result.reports[1] if len(result.reports) > 1 else {};
}
```<|im_end|>

### New Features

- **Client-only apps (`kind = "client"`)**: A project with `kind = "client"` is now auto-detected by `jac build` and `jac start` (no `--client static` flag needed). `jac build` inlines the JS bundle and CSS into a self-contained `index.html` that opens directly from disk (`file://`), and `jac start` serves it with a minimal static server (no API server, auth, or database) that still maps `/static/<name>.wasm` for `na`->wasm modules. The build flavor is also available explicitly as `--client static`; an explicit `--client` overrides the auto-detection.

### New Features

- **Feature: `fullstack` / `wasm` / `mobile` create kinds**: jac-client now contributes project-kind templates to the kind-aware `jac create`. `jac create --kind fullstack` scaffolds a server + client app, `--kind wasm` a client-only page (the former `client` template), and `--kind mobile` a mobile client app. Each stamps `[project] kind` so the project's bare `jac run` does the right thing.

### New Features

- **Feature: google-auth example wired to system-browser SSO**: The example's login and register buttons now drive the runtime's `jacSsoLogin()`, completing the previously missing `lib/auth` (AuthProvider/route guard) and storing the token under the canonical `jac_token` key so authenticated walker calls work. (jaseci-labs/jaseci#6485)

### Refactors

- **Examples drop redundant `cl` markers**: Bundled `.cl.jac` examples rely on the file extension for client context. (jaseci-labs/jaseci#6557)

### Bug Fixes

- **Fix: jac-client CLI output no longer prints raw Rich markup**: npm/bun install and config-loader messages use `console.print(..., style=)`, `console.warning`, `console.success`, and `console.error` so status lines render with correct colors on the default ANSI console.

### Refactors

- **Refactor: client plugin consumes the unified core build pipeline**: The jac-client plugin no longer ships its own copy of the bun installer, Vite bundler, and client config loader; these moved into `jaclang.runtimelib.client` so the web, pwa, mobile, and desktop targets all share one runtime and one bundler. The plugin and its targets now import these from core instead of `jac_client.plugin.src.*`. (jaseci-labs/jaseci#6390)
- **Refactor: Drop PyTauri-specific desktop handling**: Removed the `src-pytauri` setup detection/verification and the dead PyInstaller sidecar template from the client target plumbing. The `desktop` target (jac-desktop) is now a native webview build that needs no setup step.

### New Features

- **Feature: PyTauri desktop target**: The desktop build target now uses PyTauri instead of the Rust/Tauri CLI, so desktop apps no longer require a Cargo install; the PyTauri wheel bundles the Tauri runtime.
- **Feature: Plugin-provided client targets**: jac-client owns a dedicated runtime plugin surface (`JacClientPluginSpec.get_client_targets` on the `jac_client` entry-point group). Plugins such as `jac-desktop` contribute build targets without extending jaclang core; the desktop target and native sidecar register through that hook.
- **Feature: Desktop config under `[plugins.desktop]`**: Window, identifier, sidecar plugin bundling, Tauri plugins, and PyInstaller `extra_data` globs are configured under `[plugins.desktop]` (and nested `[plugins.desktop.window]`, `[plugins.desktop.plugins]`, `[plugins.desktop.bundle]`).

### Bug Fixes

- **Fix: Client error stacks resolve to the correct `.jac` line**: Per-file source maps for client modules were silently skipped during a fullstack/interop build because map generation re-fetched the module from the global hub, which such builds leave empty (client modules compile into a separate codespace). Without the map, a client-side JS error resolved to the compiled-JS line with the `.jac` filename swapped in, pointing at a line that does not exist in the source. Map generation now uses the module the compiler already produced, and also covers the client and PWA runtime files (which previously emitted no maps).
- **Fix: client function-name resolution spans both compiler programs**: The web target resolved a loaded module's compiled IR by reading `Jac.program.mod.hub` directly, which misses a jaclang-bundled app's modules (they compile into the internal program) and silently fell back to the default function name. It now resolves through the program-spanning `JacProgram.find_module`.

### Refactors

- **Refactor: One-line JSX returns across client examples and runtime**: Applied the updated formatter, collapsing short `return <Element/>;` statements onto a single line across the `jac-client` examples, fullstack template, and plugin runtime impls.

### Documentation

- **Docs: Desktop tutorial and reference**: Document PyTauri desktop setup, `[plugins.desktop]` configuration, and `jac desktop plugin` commands in the fullstack tutorial and [jac-desktop reference](../../reference/plugins/jac-desktop.md).

### New Features

- **`JacAwaiting` runtime shim**: New ambient `JacAwaiting(props)` view declaration in `client_runtime.cl.jac` -- a thin `React.Suspense` wrapper that the compiler targets when lowering `try { ... } awaiting { ... }` clauses on the `cl` target.

### Bug Fixes

- **Fix: `undefined` JSX children no longer crash the page**: A `cl` component that forwards a missing or optional prop as a JSX child (e.g. `{props.maybe}` when `maybe` isn't passed) now renders cleanly instead of blanking the page with `TypeError: Cannot read properties of undefined (reading '__jacUnsafeHtml')`.
- **Fix: reading client config no longer mutates non-client projects' `jac.toml`**: `JacClientConfig.load()` previously injected the client's npm dependency set (react, vite, typescript, …) and rewrote `jac.toml` as a side effect of merely reading client config, so any backend-only project that booted the API server gained a `[dependencies.npm]` section and had its file reserialized. The self-healing dependency migration/injection is now gated on the project having explicitly opted into the client via a `[plugins.client]` section; real client projects still self-heal as before.

### Refactors

- **Refactor: read base path via `Jac.get_base_path_dir()`**: Migrated to the new accessor; the prior `Jac.base_path_dir` class attribute has been removed.
- **Leaner fullstack starter template**: The `jac create` fullstack template is trimmed to a simpler message-based example -- the todo-app scaffolding (AuthForm, Button, TodoItem components and the template README) is removed in favor of a single MessageCard component with reworked `frontend`, `endpoints`, and `main`.

### New Features

- **Feature: Mobile target with Capacitor (Android + iOS)**: Adds `jac build --client mobile`, `jac start --client mobile`, and `jac setup mobile` -- wraps the Jac client (Vite) web app in a Capacitor native shell. Reuses the WebTarget pipeline for HTML/JS/CSS; auto-selects the dev host for Android emulator (10.0.2.2), iOS Simulator (127.0.0.1), and LAN for physical devices; supports HMR via Vite + Capacitor live-reload; checks Android/iOS toolchain prerequisites; auto-configures `adb reverse` for USB-connected Android devices. Closes #5460.

### Bug Fixes

- **Fix: Desktop sidecar bundles all PyPI dependencies correctly**: PyPI packages whose installation name differs from their import name no longer get silently dropped from the frozen desktop sidecar. `.jac` source files shipped inside Python packages are bundled alongside the `.py` files.
- **Fix: Correct assert string in `test_client_only_requires_base_url`**: The test was checking for `"client_only = true requires"` which never existed in the implementation. Updated to match the actual error message `"client_only mode requires"` in `desktop_target.impl.jac`.
- **Fix: `jacSignup` surfaces JSON parse errors instead of swallowing them**: On a 200 response with a malformed body, `jacSignup` previously returned `{success: True, user_id: None}`, hiding the failure from callers. It now returns `{success: False, error: ...}` when the response body cannot be parsed as JSON.
- **jac-client: Multi-segment SPA routes**: Fixed an issue where asset paths (JS/CSS) in the generated `index.html` were relative, causing 404 errors when refreshing on nested routes. Asset paths now use a configurable `base_path` (defaulting to `/`), which also enables deploying the app on a subpath.
- **Fix: use `{**field}` instead of `{...field}` in JacForm input JSX**: jac-client's form-input components spread the `react-hook-form` `field` registration into JSX with `{...field}`, which is JS-idiomatic but emits W0063 (`prefer-double-star-spread`) once the type checker reaches them. Switched to Jac's `{**field}` so the lint stays clean as `@jac/runtime` consumers gain stricter type checking. No runtime behavior change.

### Refactors

- **Refactor: Convert `.map(lambda)` to JSX List Comprehension in Client Runtime**: Replaced `.map(lambda → JSX)` patterns in `client_runtime.impl.jac` with native Jac JSX list comprehension syntax (`[<jsx> for item in collection]`), aligning the runtime code with idiomatic Jac style.

### New Features

- **Examples: useState → `has` Declaration Migration**: Updated `all-in-one` and `full-stack-with-auth` examples to replace React `useState` hooks with Jac-native `has` declarations. Setter callbacks passed as JSX props (e.g. `setFilter`, `setInput`) are now expressed as inline lambdas (`lambda val: str -> str { x = val; }`). The `useLocalStorage` hook was refactored to use `useEffect` for the initial localStorage load, replacing the unsupported lazy-initializer pattern.
- **Perf: Skip PyInstaller `--clean` for Faster Incremental Sidecar Builds**: The PyInstaller invocation for the desktop sidecar no longer passes `--clean`, so incremental rebuilds reuse the previous build cache instead of wiping it on every run. This significantly cuts rebuild time during iterative development. Use `jac clean` if a fully fresh build is ever needed.
- **Feat: Generate All Platform Icons for Desktop Bundles**: `_generate_default_icons` now produces all icon formats Tauri needs: `icon.ico` (Windows NSIS/MSI), `icon.icns`

Where `TypeExpression` is optional - if omitted, the ability triggers for ALL walkers.

```jac
node SecureRoom {
    has clearance_required: int;

    # Generic entry - triggers for ANY walker (no type filter)
    can on_enter with entry {
        print("Someone entered");
    }

    # Typed entry - triggers only for Inspector walkers
    can check_clearance with Inspector entry {
        if visitor.clearance < self.clearance_required {
            print("Access denied");
            disengage;
        }
    }

    # Typed entry for Root walker - in node abilities, the type in
    # 'with Type entry' refers to the *walker* type visiting this node,
    # NOT the node type. This triggers when a walker of type Root visits.
    can at_root with Root entry {
        print("A Root-type walker is visiting this node");
    }

    # Walker exiting
    can on_exit with Inspector exit {
        print("Inspector leaving");
    }

    # Multiple walker types (union)
    can process with Walker1 | Walker2 entry {
        print("Processing for Walker1 or Walker2");
    }
}
```

| Form | Triggers When |
|------|---------------|
| `with entry` | Any walker enters (no type filter) |
| `with TypeName entry` | Walker of TypeName enters |
| `with Root entry` | Walker of type Root visits (in node context, the type refers to the *walker* type) |
| `with Type1 \| Type2 entry` | Walker of either type enters |
| `with exit` | Any walker exits |
| `with TypeName exit` | Walker of TypeName exits |

### 3 Node Inheritance

```jac
node Entity {
    has created_at: str;
}

node User(Entity) {
    has username: str;
    has email: str;
}
```

## Edges

Edges are first-class connections between nodes. Unlike simple object references, edges can carry their own data (like relationship strength or timestamps) and have their own types. This lets you model rich relationships -- "Alice *knows* Bob *since 2020*" becomes natural to express. Use typed edges when the relationship itself has meaningful attributes.

### 1 Edge Declaration

```jac
edge Friend {
    has since: int;
    has strength: float = 1.0;
}

edge Follows { }  # Edge with no data

edge Weighted {
    has weight: float;

    def get_normalized(max_weight: float) -> float {
        return self.weight / max_weight;
    }
}
```

### 2 Edge Entry/Exit

Walkers can trigger abilities on edges during traversal:

```jac
edge Road {
    has distance: float;

    can on_traverse with Traveler entry {
        visitor.total_distance += self.distance;
    }
}
```

!!! warning "Known Limitation"
    Edge entry/exit abilities are not currently triggered during walker traversal. This feature is planned but not yet implemented. For now, perform edge-related logic in the walker's node abilities instead.

### 3 Directed vs Undirected

Edge direction is determined by connection operators:

```jac
node Item {}

with entry {
    a = Item();
    b = Item();

    a ++> b;          # Directed: a → b
    a <++> b;         # Undirected: a ↔ b (creates edges both ways)
}
```

### 4 Typed Edge Endpoints

By default an edge can connect *any* node types, so a neighbour traversal such as `[here ->:Friend:->]` has element type `any` and needs a `[?:Type]` filter before you can read a field off the result. You can instead declare the **source** and **target** node types an edge connects, after a `:`, using the traversal arrow so it reads like the navigation it enables:

```jac
node Profile { has name: str = ""; }
node Tweet { has content: str = ""; }

edge Follow: Profile --> Profile {}      # Profile → Profile
edge Post: Profile --> Tweet {}          # Profile → Tweet
```

With endpoints declared, a neighbour traversal **infers the declared node type** -- no `[?:Type]` filter needed:

```jac
with entry {
    me = Profile(name="me");
    following = [me ->:Follow:->];   # inferred list[Profile] (target)
    followers = [me <-:Follow:<-];   # inferred list[Profile] (source)
    my_tweets = [me ->:Post:->];     # inferred list[Tweet]

    # The element type is concrete, so field access resolves statically
    # (and compiles on the native backend) -- no filter required:
    if following {
        print(following[0].name);
    }
}
```

An outgoing traversal (`->:Edge:->`) narrows to the **target** type; an incoming traversal (`<-:Edge:<-`) narrows to the **source** type. A `[?:Sub]` filter can still narrow *further* to a subtype.

Typed endpoints are **opt-in and gradual**: an untyped `edge Link {}` keeps `any → any` connectivity and `list[any]` traversal results, so existing code is unaffected. The endpoint type is a **bound** -- `Profile` *or a subtype* -- so subclass-heterogeneous graphs stay valid.

The `()` after the name remains reserved for **edge inheritance**, orthogonal to the endpoints. A subtype edge inherits its base edge's endpoints unless it re-declares them:

```jac
edge TimedFollow(Follow) { has at: str = ""; }          # inherits Profile → Profile
edge BlockedFollow(Follow): Profile --> Profile {}      # re-declares its endpoints
```

The endpoint clause is only valid on an `edge`; placing it on a `node`, `walker`, or `obj` is a compile error (`E2027`).

## Walkers

Walkers are mobile agents that traverse the graph, executing abilities at each node they visit. Unlike functions that you call, walkers *go to* data. They maintain state throughout their journey, making them ideal for tasks like collecting information across a graph, implementing AI agents that navigate knowledge structures, or processing pipelines where context accumulates. Spawn a walker with `root spawn MyWalker()` to begin traversal.

### 1 Walker Declaration

```jac
walker Collector {
    has items: list = [];
    has max_items: int = 10;

    can start with Root entry {
        print("Starting collection");
        visit [-->];
    }

    can collect with DataNode entry {
        if len(self.items) < self.max_items {
            self.items.append(here.value);
        }
        visit [-->];
    }
}
```

### 2 Walker State

Walkers maintain state throughout their traversal:

```jac
node DataNode {
    has value: int;
}

walker Counter {
    has count: int = 0;

    can start with Root entry {
        self.count += 1;
        visit [-->];
    }

    can count_nodes with DataNode entry {
        self.count += 1;
        visit [-->];
    }
}

with entry {
    root ++> DataNode(value=1) ++> DataNode(value=2);
    walker_instance = Counter();
    root spawn walker_instance;
    print(f"Counted {walker_instance.count} nodes");  # Output: 3
}
```

> **Note:** Walker abilities must specify which node types they handle. Use `Root` for the root node and specific node types for others. A generic `with entry` only triggers at the spawn location.

### 3 The `visit` Statement

The `visit` statement tells the walker where to go next. It doesn't immediately move -- it queues nodes for the next step of traversal. This queue-based approach lets you control breadth-first vs depth-first traversal and handle cases where there's nowhere to go (using the `else` clause).

!!! warning "Traversal Must Be Explicit"
    Without a `visit` statement in an ability, the walker stops at the current node. If a walker visits root and then reaches a `Person` node but the `Person` ability has no `visit [-->]`, the walker will not continue to the next person. Traversal must be explicitly requested at each step.

```jac
node Item {}

walker Visitor {
    can go with Item entry {
        visit [-->];                    # Visit all outgoing nodes
        visit [<--];                    # Visit all incoming nodes
        visit [<-->];                   # Visit both directions
    }
}
```

```jac
node Person {}
edge Friend { has since: int = 2020; }

walker Visitor {
    can filter with Person entry {
        visit [-->][?:Person];          # Visit Person nodes only
        visit [->:Friend:->];           # Visit via Friend edges only
        visit [->:Friend:since>2020:->]; # Via Friend edges with condition
    }
}
```

```jac
node Item {}

walker Visitor {
    can traverse with Item entry {
        visit [-->] else {              # Fallback if no nodes to visit
            print("No outgoing edges");
        }
    }
}
```

```jac
node Item {}

walker Visitor {
    has target: Item | None = None;

    can direct with Item entry {
        visit here;                     # Visit current node
        visit self.target;              # Visit node stored in walker field
    }
}
```

The `visit : index : [-->]` syntax controls *where* in the walker's traversal queue new destinations are inserted. This enables DFS, BFS, and custom traversal strategies:

```jac
node Item {}

walker Visitor {
    can traverse with Item entry {
        visit : 0 : [-->];              # Insert at FRONT of queue (DFS behavior)
        visit : -1 : [-->];             # Insert at END of queue (BFS behavior)
        visit : 2 : [-->];              # Insert at position 2 in queue
    }
}
```

| Syntax | Queue Position | Effect |
|--------|---------------|--------|
| `visit [-->]` | End (default) | BFS-like -- standard breadth-first traversal |
| `visit : 0 : [-->]` | Front | DFS-like -- depth-first by inserting at front |
| `visit : -1 : [-->]` | End | Explicit BFS -- same as default |
| `visit : N : [-->]` | Position N | Custom insertion point |

Out-of-bounds indices fall back to appending at the end.

### 4 The `report` Statement

Send data back without stopping. Each `report` appends to the `.reports` array and also prints the value to stdout.

!!! note
    `report value;` both adds `value` to `.reports` **and** prints it to stdout. Keep this in mind when reading output from walker examples.

```jac
node DataNode {
    has value: int = 0;
}

walker DataCollector {
    can start with Root entry {
        visit [-->];
    }

    can collect with DataNode entry {
        report here.value;  # Continues execution
        visit [-->];
    }
}

with entry {
    root ++> DataNode(value=1);
    result = root spawn DataCollector();
    all_values = result.reports;  # List of reported values
}
```

You can declare `has reports` with a type to get compile-time checking on `report` statements:

```jac
walker DataCollector {
    has reports: list[int];

    can start with Root entry { visit [-->]; }
    can collect with DataNode entry {
        report here.value;  # checked against int
        visit [-->];
    }
}
```

If omitted, `reports` defaults to `list[any]`. See [Walker Response Patterns](walker-responses.md#typing-your-reports) for details.

### 5 The `disengage` Statement

The `disengage` statement immediately terminates a walker's traversal. Use it when the walker has found what it was looking for (like a search hitting its target) or when a condition means further traversal would be pointless. It's the walker equivalent of `return` from a recursive function.

```jac
walker Searcher {
    has target: str;

    can search with Person entry {
        if here.name == self.target {
            report here;
            disengage;  # Stop traversal
        }
        visit [-->];
    }
}
```

#### `skip` vs `disengage`

`skip` and `disengage` are easy to confuse, but they operate at different scopes. `skip` is a return-family statement (alongside `return`/`yield`/`report`) -- it is **not** a loop control like `continue`, despite the "skip an iteration" connotation of the word.

| Statement | Effect |
|-----------|--------|
| `skip;` | Returns from the **current ability only** -- equivalent to a bare `return;`. The walker continues: any sibling abilities bound to the same node still run, and traversal proceeds through nodes already queued by `visit`. |
| `disengage;` | Terminates the **whole walker** -- no further abilities run and no further nodes are visited. |

Because `skip` is just an early `return`, a `skip` reached *before* this ability's `visit` statement means this ability queued no next nodes; the walker will only continue to nodes queued elsewhere (and stops if none remain).

```jac
walker Auditor {
    can check with Account entry {
        if not here.active {
            skip;          # this account isn't ours to process; move on
        }
        report here.balance;
        visit [-->];       # not reached for inactive accounts
    }
}
```

### 6 Spawning Walkers

```jac
node Item { has value: int = 0; }

walker MyWalker {
    has param: int = 0;

    can visit with Root entry {
        visit [-->];
    }
    can collect with Item entry {
        report here.value;
        visit [-->];
    }
}

with entry {
    node1 = Item(value=1);
    node2 = Item(value=2);
    node3 = Item(value=3);
    root ++> node1 ++> node2 ++> node3;

    # Basic spawn
    result = root spawn MyWalker();

    # Spawn with parameters
    result = root spawn MyWalker(param=10);

    # Access results
    print(result.reports);  # All reported values
}
```

### When to Use Walkers vs Functions

Jac provides two ways to expose server logic: `def:pub` functions and `walker` types. Choose based on your needs:

| | `def:pub` Functions | Walkers |
|---|---|---|
| **Best for** | Simple stateless CRUD, quick prototyping | Graph traversal, per-user data, production apps |
| **Auth** | Shared data (no user isolation) | Per-user root node (`walker:priv` enforces auth) |
| **Data access** | Direct: `[root -->]` | Traversal: `visit [-->]`, `here` |
| **API style** | Function call → HTTP endpoint | Spawn walker at node |
| **State** | Stateless | Carries state across nodes via `has` properties |

!!! tip "Rule of Thumb"
    Start with `def:pub` to prototype quickly. Switch to walkers when you need authentication, per-user data isolation, or multi-step graph traversal. The `walker:priv` visibility modifier automatically enforces that the walker runs on the authenticated user's private root node.

### Walkers as REST APIs

Public walkers automatically become HTTP endpoints when you run `jac start`:

```jac
node Todo {
    has title: str;
    has done: bool = False;
}

walker add_todo {
    has title: str;

    can create with Root entry {
        new_todo = here ++> Todo(title=self.title);
        report new_todo;
    }
}

walker list_todos {
    can list with Root entry {
        for todo in [-->][?:Todo] {
            report todo;
        }
    }
}
```

!!! note
    `main.jac` is the default entry point. If your file has a different name (e.g., `app.jac`), pass it explicitly: `jac start app.jac`.

```bash
# Run as API server
jac start

# Call via HTTP
curl -X POST http://localhost:8000/walker/add_todo \
  -H "Content-Type: application/json" \
  -d '{"title": "Learn OSP"}'
```

Walker `has` properties become the request body. The `report` values become the response. See [Part IV: Full-Stack](../plugins/jac-client.md) and the [Scale Reference](../plugins/jac-scale.md) for full API documentation.

