- Remove the `let` keyword from all variable declarations
- Use direct assignment (`x = value`) instead of `let x = value`
- This applies to all contexts including destructuring assignments

> **Note for client-side code:** In `cl {}` blocks and `.cl.jac` files, prefer using `has` for reactive state (see v0.9.5 reactive state feature) instead of explicit `useState` destructuring.

#### 1. byLLM Imports Moved to `byllm.lib`

All byLLM exports have been moved under the `byllm.lib` module to enable lazy loading and faster startup. Direct imports from `byllm` are removed.

```jac
import from byllm { Model }

glob llm = Model(model_name="gpt-4o-mini", verbose=True);
```

```jac
import from byllm.lib { Model }

glob llm = Model(model_name="gpt-4o-mini", verbose=True);
```

#### 1. `check` Keyword Removed - Use `assert` in Test Blocks

The `check` keyword has been removed from Jaclang. All testing functionality is now unified under `assert` statements, which behave differently depending on context: raising exceptions in regular code and reporting test failures within `test` blocks.

```jac
glob a: int = 5;
glob b: int = 2;

test "equality" {
    check a == 5;
    check b == 2;
}

test "comparison" {
    check a > b;
    check a - b == 3;
}

test "membership" {
    check "a" in "abc";
    check "d" not in "abc";
}

test "function result" {
    check almostEqual(a + b, 7);
}
```

```jac
glob a: int = 5;
glob b: int = 2;

test "equality" {
    assert a == 5;
    assert b == 2;
}

test "comparison" {
    assert a > b;
    assert a - b == 3;
}

test "membership" {
    assert "a" in "abc";
    assert "d" not in "abc";
}

test "function result" {
    assert almostEqual(a + b, 7);
}
```

- Replace all `check` statements with `assert` statements in test blocks
- `assert` statements in test blocks report test failures without raising exceptions
- `assert` statements outside test blocks continue to raise `AssertionError` as before
- Optional error messages can be added: `assert condition, "Error message";`

This change unifies the testing and validation syntax, making the language more consistent while maintaining all testing capabilities.

#### 1. Global, Nonlocal Operators Updated to `global`, `nonlocal`

This renaming aims to make the operator's purpose align with python, as `global`, `nonlocal` more aligned with python.

```jac
glob x = "Jaclang ";

def outer_func -> None {
    :global: x; # :g: also correct

    x = 'Jaclang is ';
    y = 'Awesome';
    def inner_func -> tuple[str, str] {
        :nonlocal: y; #:nl: also correct

        y = "Fantastic";
        return (x, y);
    }
    print(x, y);
    print(inner_func());
}

with entry {
    outer_func();
}
```

```jac
glob x = "Jaclang ";

def outer_func -> None {
    global x;

    x = 'Jaclang is ';
    y = 'Awesome';
    def inner_func -> tuple[str, str] {
        nonlocal y;

        y = "Fantastic";
        return (x, y);
    }
    print(x, y);
    print(inner_func());
}

with entry {
    outer_func();
}
```

#### 2. `mtllm.llms` Module Replaced with Unified `mtllm.llm {Model}`

The mtllm library now uses a single unified Model class under the `mtllm.llm` module, instead of separate classes like `Gemini` and `OpenAI`. This simplifies usage and aligns model loading with HuggingFace-style naming conventions.

```jac
import from mtllm.llms { Gemini, OpenAI }

glob llm1 = Gemini(model_name="gemini-2.0-flash");
glob llm2 = OpenAI();
```

```jac
import from mtllm.llm { Model }

glob llm1 = Model(model_name="gemini/gemini-2.0-flash");
glob llm2 = Model(model_name="gpt-4o");
```

#### 1. `dotgen` Builtin Function Renamed to `printgraph`

This renaming aims to make the function's purpose clearer, as `printgraph` more accurately reflects its action of outputting graph data, similar to how it can also output in JSON format. Also other formats may be added (like mermaid).

```jac
node N {has val: int;}
edge E {has val: int = 0;}

with entry {
    end = root;
    for i in range(0, 2) {
        end +>: E : val=i :+> (end := [ N(val=i) for i in range(0, 2) ]);
    }
    data = printgraph(node=root);
    print(data);
}
```

#### 2. `ignore` Feature Removed

This removal aims to avoid being over specific with object-spatial features.

```jac
node MyNode {
    has val:int;
}

walker MyWalker {
    can func1 with MyNode entry {
        ignore [here];
        visit [-->]; # before
        print(here);
    }
}

with entry {
    n1 = MyNode(5);
    n1 ++> MyNode(10) ++> MyNode(15) ++> n1; # will result circular
    n1 spawn MyWalker();
}
```

```jac
node MyNode {
    has val:int;
}

walker MyWalker {
    has Ignore: list = [];

    can func1 with MyNode entry {
        self.Ignore.append(here); # comment here to check the circular graph
        visit [i for i in [-->] if i not in self.Ignore]; # now
        print(here);
    }
}

with entry {
    n1 = MyNode(5);
    n1 ++> MyNode(10) ++> MyNode(15) ++> n1; # will result circular
    n1 spawn MyWalker();
}
```

#### 1. `impl` Keyword Introduced to Simplify Implementation

The new `impl` keyword provides a simpler and more explicit way to implement abilities and methods for objects, nodes, edges, and other types. This replaces the previous more complex colon-based syntax for implementation.

```jac
:obj:Circle:def:area -> float {
    return math.pi * self.radius * self.radius;
}

:node:Person:can:greet with Room entry {
    print("Hello, I am " + self.name);
}

:def:calculate_distance(x: float, y: float) -> float {
    return math.sqrt(x*x + y*y);
}
```

```jac
impl Circle.area -> float {
    return math.pi * self.radius * self.radius;
}

impl Person.greet with Room entry {
    return "Hello, I am " + self.name;
}

impl calculate_distance(x: float, y: float) -> float {
    return math.sqrt(x*x + y*y);
}
```

This change makes the implementation syntax more readable, eliminates ambiguity, and better aligns with object-oriented programming conventions by using the familiar dot notation to indicate which type a method belongs to.

#### 2. Inheritance Base Classes Specification Syntax Changed

The syntax for specifying inheritance has been updated from using colons to using parentheses, which better aligns with common object-oriented programming languages.

```jac
obj Vehicle {
    has wheels: int;
}

obj Car :Vehicle: {
    has doors: int = 4;
}

node BaseUser {
    has username: str;
}

node AdminUser :BaseUser: {
    has is_admin: bool = true;
}
```

```jac
obj Vehicle {
    has wheels: int;
}

obj Car(Vehicle) {
    has doors: int = 4;
}

node BaseUser {
    has username: str;
}

node AdminUser(BaseUser) {
    has is_admin: bool = true;
}
```

This change makes the inheritance syntax more intuitive and consistent with languages like Python, making it easier for developers to understand class hierarchies at a glance.

#### 3. `def` Keyword Introduced

Instead of using `can` keyword for all functions and abilities, `can` statements are only used for object-spatial abilities and `def` keyword must be used for traditional python like functions and methods.

```jac
can add(x: int, y: int) -> int {
    return x + y;
}

node Person {
    has name;
    has age;

    can get_name {
        return self.name;
    }

    can greet with speak_to {
        return "Hello " + visitor.name + ", my name is " + self.name;
    }

    can calculate_birth_year {
        return 2025 - self.age;
    }
}
```

```jac
def add(x: int, y: int) -> int {
    return x + y;
}

node Person {
    has name;
    has age;

    def get_name {
        return self.name;
    }

    can greet with speak_to entry {
        return "Hello " + visitor.name + ", my name is " + self.name;
    }

    def calculate_birth_year {
        return 2025 - self.age;
    }
}
```

#### 4. `visitor` Keyword Introduced

Instead of using `here` keyword to represent the other object context while `self` is the self referential context. Now `here` can only be used in walker abilities to reference a node or edge, and `visitor` must be used in nodes/edges to reference the walker context.

```jac
node Person {
    has name;

    can greet {
        self.name = self.name.upper();
        return "Hello, I am " + self.name;
    }

    can update_walker_info {
        here.age = 25;  # 'here' refers to the walker
    }
}

walker PersonVisitor {
    has age;

    can visit: Person {
        here.name = "Visitor";  # 'here' refers to the current node
        report here.greet();
    }
}
```

```jac
node Person {
    has name;

    can greet {
        self.name = self.name.upper();
        return "Hello, I am " + self.name;
    }

    can update_walker_info {
        visitor.age = 25;  # 'visitor' refers to the walker
    }
}

walker PersonVisitor {
    has age;

    can visit: Person {
        here.name = "Visitor";  # 'here' still refers to the current node in walker context
        report here.greet();
    }
}
```

- `self`: The current object (node or edge) referring to itself
- `visitor`: The walker interacting with a node/edge
- `here`: Used only in walker abilities to reference the current node/edge being visited

#### 5. Lambda Syntax Updated

Instead of using the `with x: int can x;` type syntax the updated lambda syntax now replaces `with` and `can` with `lambda` and `:` respectively.

```jac
# Lambda function syntax with 'with' and 'can'
with entry {
    square_func = with x: int can x * x;
}
```

```jac
# Updated lambda
with entry {
    square_func = lambda x: int: x * x;
}
```

This change brings Jac's lambda syntax closer to Python's familiar `lambda parameter: expression` pattern, making it more intuitive for developers coming from Python backgrounds while maintaining Jac's type annotations.

#### 6. Object-Spatial Arrow Notation Updated

The syntax for typed arrow notations are updated as `-:MyEdge:->` and `+:MyEdge:+>` is now `->:MyEdge:->` and `+>:MyEdge:+>` for reference and creations.

```jac
friends = [-:Friendship:->];
alice <+:Friendship:strength=0.9:+ bob;
```

```jac
friends = [->:Friendship:->];
alice <+:Friendship:strength=0.9:<+ bob;
```

This change was made to eliminate syntax conflicts with Python-style list slicing operations (e.g., `my_list[:-1]` was forced to be written `my_list[: -1]`). The new arrow notation provides clearer directional indication while ensuring that object-spatial operations don't conflict with the token parsing for common list operations.

#### 7. Import `from` Syntax Updated for Clarity

The syntax for importing specific modules or components from a package has been updated to use curly braces for better readability and to align with modern language conventions.

```jac
import from pygame_mock, color, display;
import from utils, helper, math_utils, string_formatter;
```

```jac
import from pygame_mock { color, display };
import from utils { helper, math_utils, string_formatter };
```

This new syntax using curly braces makes it clearer which modules are being imported from which package, especially when importing multiple items from different packages.

#### 8. Import Statements Auto-Resolved (No Language Hints Needed)

The language-specific import syntax has been simplified by removing the explicit language annotations (`:py` and `:jac`). The compiler now automatically resolves imports based on context and file extensions.

```jac
import:py requests;
import:jac graph_utils;
import:py json, os, sys;
```

```jac
import requests;
import graph_utils;
import json, os, sys;
```

This change simplifies the import syntax, making code cleaner while still maintaining the ability to import from both Python and Jac modules. The Jac compiler now intelligently determines the appropriate language context for each import.

#### 9. `restrict` and `unrestrict` Renamed to `perm_grant` and `perm_revoke`

The permission management API has been renamed to better reflect its purpose and functionality.

```jac
walker create_item {
    can create with Root entry {
        new_item = spawn Item(name="New Item");
        Jac.unrestrict(new_item, level="CONNECT");  # Grant permissions
        Jac.restrict(new_item, level="WRITE");      # Revoke permissions
    }
}
```

```jac
walker create_item {
    can create with Root entry {
        new_item = spawn Item(name="New Item");
        Jac.perm_grant(new_item, level="CONNECT");  # Grant permissions
        Jac.perm_revoke(new_item, level="WRITE");   # Revoke permissions
    }
}
```

This change makes the permission management API more intuitive by using verbs that directly describe the actions being performed.<|im_end|>

# Jaclang Release Notes

This document provides a summary of new features, improvements, and bug fixes in each version of **Jaclang**. For details on changes that might require updates to your existing code, please refer to the [Breaking Changes](../breaking-changes.md) page.

### Breaking Changes

- **Breaking: language clean-break -- `global`/`nonlocal` removed in favor of lexical rebinding, plus operator and keyword cleanup (issue #7514)**: A coordinated set of syntax removals with no deprecation path. (1) The `global` and `nonlocal` directive statements are gone: a bare assignment (including `+=` and `:=`) inside a function now binds to the nearest enclosing binding -- an enclosing function's local, or a module-level `glob` variable -- and creates a new local only when no such binding exists. Only `glob`-declared variables are implicitly rebindable; assigning a name that matches a module-level import, function, or class still creates a local. Shadowing an outer binding requires a typed declaration (`x: int = 5;`) placed before any use of the name in that scope (E0064 otherwise), and loop / `except ... as` / `with ... as` targets always bind fresh locals. Migration: delete `global`/`nonlocal` lines; add a typed declaration where a function intentionally shadowed a `glob` name. This also fixes the inherited Python gotcha where `x += 1` against a module global raised `UnboundLocalError`. (2) `&&` and `||` are removed -- `and`/`or` are the only spellings. (3) The abstract marker is renamed `abs` → `abst`; `abs` is again only the builtin function. (4) The parenthesized filter form `(?:Type, cond)` / `(?cond)` is removed (E0048) -- use the bracket form `[?:Type, cond]` / `[?cond]`. (5) The `root()` call form is removed (E0049) -- use bare `root` in Jac source (Python library-mode `root()` calls are unchanged). (6) Deferred fields drop the `by`: `has x: T postinit;`. (7) The C-style for loop is respelled `for i = 0 while i < 10 with i += 1 { }` -- the condition may be any full expression, and `to` is no longer a keyword (identifiers named `to` no longer need backtick escapes). (8) Backtick keyword-escaping is unified, and Python reserved words (`class`, `lambda`, ...) are now rejected as `has`-field or parameter names at compile time (E0067) instead of crashing at runtime.

### New Features

- **Feature: Format cache for `jac fmt`**: Add `jac fmt --cache` (`-C`) flag that skips files already known to be formatted, keyed on content digest + effective `[format]`/`[check]` config (including suppress settings) + formatter-pipeline fingerprint (+ logical path under `--lintfix`). Entries live under `.jac/cache/fmt-v1/` (including outside a project) with atomic writes and self-healing corruption recovery. Enabled automatically in `jac precommit`; `--staged --verify` preserves project logical paths while caching staged blob bytes. Caching is skipped with `--to_screen`. Annex failures are never cached as clean. The store is self-bounding: cache hits refresh entry recency, and writes opportunistically prune (at most once per day) entries unused for 30 days, evict oldest-first past 20k entries, and sweep temp files orphaned by crashed writers. No behavior change when `--cache` is omitted.
- **Gateway-owned identity for microservice mode**: the gateway now serves `/user/register`, `/user/login`, `/user/refresh-token`, `/user/password`, and `/user/me` from its own user manager instead of passing them through to an arbitrary service, and services JIT-provision a local user record + root for validly-signed tokens they have not seen (microservice siblings only). Previously, identity landed in whichever service answered the passthrough first, so walkers in any other service failed with a 500 `User not found`; that

```jac
import from jaclang.byllm.lib { Model }

glob llm = Model(
    model_name="gpt-4o",
    api_key="your_litellm_virtual_key",
    config={"api_base": "http://localhost:8000"}
);
```

```python
from jaclang.byllm.lib import Model

llm = Model(
    model_name="gpt-4o",
    api_key="your_litellm_virtual_key",
    config={"api_base": "http://localhost:8000"}
)
```

### Parameters

| Parameter | Description |
|-----------|-------------|
| `model_name` | The model to use (must be configured in LiteLLM proxy) |
| `api_key` | LiteLLM virtual key or master key (not the provider API key) |
| `config` | Configuration dict; set `api_base` to the URL of your LiteLLM proxy server (also accepts `base_url` or `host` as aliases) |

For virtual key generation, see [LiteLLM Virtual Keys](https://docs.litellm.ai/docs/proxy/virtual_keys).

### Enabling Telemetry in LiteLLM Proxy Server

When serving with the built-in scale subsystem (`jac start`), LLM telemetry is automatically enabled. The server registers both a **litellm CustomLogger** (for per-call token/cost tracking) and a **byLLM agent callback** (for per-invocation metadata), then exposes REST endpoints for querying the collected data.

| Endpoint | Description |
|----------|-------------|
| `GET /admin/llm/telemetry/summary` | Aggregate stats: total calls, tokens, cost, latency, per-model and per-caller breakdowns |
| `GET /admin/llm/telemetry/traces` | Paginated list of invocation traces (supports `?caller=`, `?model=`, `?status=` filters) |
| `GET /admin/llm/telemetry/traces/{id}` | Full detail for a single trace including all associated LLM call records |
| `GET /admin/llm/telemetry/filters` | Available filter values (callers, models, statuses) |

All endpoints require admin authentication via the `Authorization` header.

## Creating Custom Model Classes

For self-hosted models or custom APIs not supported by LiteLLM, create a custom model class by inheriting from `BaseLLM`.

### Implementation

=== "Python"
    ```python
    from jaclang.byllm.llm import BaseLLM
    from openai import OpenAI

    class MyCustomModel(BaseLLM):
        def __init__(self, model_name: str, **kwargs) -> None:
            """Initialize the custom model."""
            super().__init__(model_name, **kwargs)

        def model_call_no_stream(self, params):
            """Handle non-streaming calls."""
            client = OpenAI(api_key=self.api_key)
            response = client.chat.completions.create(**params)
            return response

        def model_call_with_stream(self, params):
            """Handle streaming calls."""
            client = OpenAI(api_key=self.api_key)
            response = client.chat.completions.create(stream=True, **params)
            return response
    ```

=== "Jac"
    ```jac
    import from jaclang.byllm.llm { BaseLLM }
    import from openai { OpenAI }

    obj MyCustomModel(BaseLLM) {
        has model_name: str;
        has config: dict = {};

        def post_init() {
            super().__init__(model_name=self.model_name, **self.config);
        }

        def model_call_no_stream(params: dict) -> object {
            client = OpenAI(api_key=self.api_key);
            response = client.chat.completions.create(**params);
            return response;
        }

        def model_call_with_stream(params: dict) -> object {
            client = OpenAI(api_key=self.api_key);
            response = client.chat.completions.create(stream=True, **params);
            return response;
        }
    }
    ```

### Usage

```jac
glob llm = MyCustomModel(model_name="my-custom-model");

def generate(prompt: str) -> str by llm();
```

### Required Methods

| Method | Description |
|--------|-------------|
| `model_call_no_stream(params)` | Handle standard (non-streaming) LLM calls |
| `model_call_with_stream(params)` | Handle streaming LLM calls |

The `params` dictionary contains the formatted request including messages, model name, and any additional parameters.

## Advanced Python Integration

byLLM provides two modes for Python integration:

### Mode 1: Direct Python Import

Import byLLM directly in Python using the `@by` decorator:

```python
from dataclasses import dataclass
from jaclang.byllm.lib import Model, Image, by

llm = Model(model_name="gpt-4o")

@dataclass
class Person:
    full_name: str
    description: str
    year_of_birth: int

@by(llm)
def get_person_info(img: Image) -> Person: ...

# Usage
img = Image("photo.jpg")
person = get_person_info(img)
print(f"Name: {person.full_name}")
```

### Mode 2: Implement in Jac, Import to Python (Recommended)

Implement AI features in Jac and import seamlessly into Python:

=== "ai.jac"
    ```jac
    import from jaclang.byllm.lib { Image }

    obj Person {
        has full_name: str;
        has description: str;
        has year_of_birth: int;
    }

    sem Person.description = "Short biography";

    def get_person_info(img: Image) -> Person by llm();
    sem get_person_info = "Extract person information from the image.";
    ```

=== "main.py"
    ```python
    from ai import Image, Person, get_person_info

    img = Image("photo.jpg")
    person = get_person_info(img)
    print(f"Name: {person.full_name}")
    ```

### Semstrings in Python

Use the `@Jac.sem` decorator for semantic strings in Python:

```python
from jaclang import JacRuntimeInterface as Jac
from dataclasses import dataclass
from jaclang.byllm.lib import Model, by

llm = Model(model_name="gpt-4o")

@Jac.sem("Represents a personal record", {
    "name": "Full legal name",
    "dob": "Date of birth (YYYY-MM-DD)",
    "ssn": "Last four digits of Social Security Number"
})
@dataclass
class Person:
    name: str
    dob: str
    ssn: str

@by(llm)
def check_eligibility(person: Person, service: str) -> bool: ...
```

### Hyperparameters in Python

```python
@by(llm(temperature=0.3, max_tokens=100))
def generate_joke() -> str: ...
```

### Tools in Python

```python
def get_weather(city: str) -> str:
    return f"The weather in {city} is sunny."

@by(llm(tools=[get_weather]))
def answer_question(question: str) -> str: ...
```

### AI Agents as Walkers

Combine graph traversal with LLM reasoning by using walkers as AI agents:

```jac
node Place {
    has name: str;
}

def decide_action(goal: str, current: str, memory: list[dict]) -> str by llm();
sem decide_action = "Given the agent's goal, current location, and memory of past decisions, decide the next action.";

walker AIAgent {
    has goal: str;
    has memory: list[dict] = [];

    can decide with Place entry {
        decision = decide_action(self.goal, here.name, self.memory);
        self.memory.append({"location": here.name, "decision": decision});
        visit [-->];
    }
}
```

### LLM-Guided Traversal (`visit ... by llm`)

A plain `visit [-->]` queues **every** matching successor. Add `by llm()` and the
model decides which successor(s) the walker should visit next. This is useful when the
next hop depends on the meaning of each edge/node rather than a hard-coded filter.

In its simplest form you add nothing but `by llm()`:

```jac
walker dispatcher {
    has request: str = "urgent escalation";

    can route with Desk entry {
        visit [-->] by llm();
    }
}
```

With no parameters, the model routes from context alone. Each candidate is rendered as
an **(edge, node) pair** relative to the current node, so the model can condition on the
connecting edge's type and attributes, not just node data. The walker's own state plus
the current node are injected automatically (no need to smuggle them through
`incl_info`). Candidate, field, and ability descriptions are sourced from
[semstrings](#semantic-strings-semstrings). By default `select` is `"all"`, so the
walker visits **every** successor the model picks.

This bare form leans entirely on those descriptions, so it works best when your edges,
nodes, and the walker carry meaningful `sem` strings. The two parameters below sharpen
the decision.

#### Steering the choice with `intent`

`intent` is free-text shown to the model describing what the traversal is trying to
achieve. It is the main lever for guiding routing:

```jac
walker dispatcher {
    can route with Desk entry {
        visit [-->] by llm(intent="Route along the highest-priority edge");
    }
}
```

#### Constraining how many nodes are visited

The `select` parameter caps the cardinality of the result. The model is told the
constraint in its prompt **and** the returned selection is truncated to honor it:

| `select` value | Meaning |
|----------------|---------|
| `"all"` *(default)* | Visit every successor the model chooses (no cap). |
| `1` | Visit **exactly one** successor (the single best match). |
| `k` *(int)* | Visit **exactly `k`** successors. |
| `(min, max)` *(tuple)* | Visit **between `min` and `max`** successors, inclusive. |

```jac
walker explorer {
    can branch with Page entry {
        # Pick the single best next node
        visit [-->] by llm(select=1, intent="Go to the most relevant section");

        # Fan out to at most three, at least one
        visit [-->] by llm(select=(1, 3), intent="Explore the promising branches");

        # Take exactly two
        visit [-->] by llm(select=2, intent="Compare the two strongest candidates");
    }
}
```

!!! note
    `select` bounds the count; it does not force it upward when too few candidates
    qualify. With `select=2` but only one sensible successor, the walker visits one.
    For `(min, max)`, `max` is a **hard cap** (the result is truncated to it), but
    `min` is **advisory**: the model is *asked* to pick at least `min`, yet routing
    can only visit candidates the model actually chose (and there may be fewer than
    `min` available), so a shortfall is surfaced as a warning rather than enforced.

### Tool-Using Agents

Agents combine LLM reasoning with tool functions. The LLM decides which tools to call and in what order (ReAct loop):

```jac
import from jaclang.byllm.lib { Model }

glob llm = Model(model_name="gpt-4o");

glob kb: dict = {
    "products": ["Widget A", "Widget B", "Service X"],
    "prices": {"Widget A": 99, "Widget B": 149, "Service X": 29},
    "inventory": {"Widget A": 50, "Widget B": 0, "Service X": 999}
};

"""List all available products."""
def list_products() -> list[str] {
    return kb["products"];
}

"""Get the price of a product."""
def get_price(product: str) -> str {
    if product in kb["prices"] {
        return f"${kb['prices'][product]}";
    }
    return "Product not found";
}

"""Check if a product is in stock."""
def check_inventory(product: str) -> str {
    qty = kb["inventory"].get(product, 0);
    return f"In stock ({qty} available)" if qty > 0 else "Out of stock";
}

def sales_agent(request: str) -> str by llm(
    tools=[list_products, get_price, check_inventory]
);
sem sales_agent = "Help customers browse products, check prices and availability.";
```

### Context Injection with `incl_info`

Pass additional runtime context to the LLM without modifying function signatures:

```jac
glob company_info = """
Company: TechCorp
Products: CloudDB, SecureAuth, DataViz
Support Hours: 9 AM - 5 PM EST
""";

def support_agent(question: str) -> str by llm(
    incl_info={"company_context": company_info}
);
sem support_agent = "Answer customer questions about our products and services.";
```

The `incl_info` dict keys and values are injected into the prompt as additional context. This is useful for dynamic information that changes between calls.

### Agentic Walkers

Walkers that traverse document graphs and use LLM for analysis:

```jac
node Document {
    has title: str;
    has content: str;
    has summary: str = "";
}

def summarize(content: str) -> str by llm();
sem summarize = "Summarize this document in 2-3 sentences.";

walker DocumentAgent {
    has query: str;

    can process with Root entry {
        all_docs = [-->][?:Document];

        for doc in all_docs {
            if self.query.lower() in doc.content.lower() {
                doc.summary = summarize(doc.content);
                report {"title": doc.title, "summary": doc.summary};
            }
        }
    }
}
```

### Multi-Agent Systems

Orchestrate multiple specialized walkers:

```jac
walker Coordinator {
    can coordinate with Root entry {
        research = root spawn Researcher(topic="AI");
        writer = root spawn Writer(style="technical");
        reviewer = root spawn Reviewer();

        report {
            "research": research.reports,
            "draft": writer.reports,
            "review": reviewer.reports
        };
    }
}
```<|im_end|>

# NPM Packages & UI Libraries

Jac's client-side compiler gives you full access to the npm ecosystem. You can import React hooks, UI component libraries, utility packages, and any other npm module directly into your `.cl.jac` files. This tutorial covers how to add npm dependencies, import them, and integrate popular UI libraries like Tailwind CSS and shadcn/ui.

!!! note "npm imports and `jac check`"
    `jac check` types client npm imports from each package's `.d.ts` when declarations are installed (functions, constants, type aliases, and structural `interface`/`class` members). Constructs the checker does not model yet, or packages with no declarations, still surface as foreign `any` (`W1102`, or `E1120` when `[check] untyped-external = "error"`). See [npm import type checking](../../reference/plugins/jac-client.md#npm-import-type-checking-jac-check) in the Full Reference.

### Via jac.toml

Declare dependencies in your `jac.toml` file under `[dependencies.npm]`:

```toml
[dependencies.npm]
"@radix-ui/react-slot" = "*"
"class-variance-authority" = "^0.7.1"
"sonner" = "^2.0.0"
"react-markdown" = "latest"
"@monaco-editor/react" = "^4.7.0"
"@hugeicons/react" = "*"
"@hugeicons/core-free-icons" = "*"

[dependencies.npm.dev]
"@tailwindcss/vite" = "latest"
tailwindcss = "latest"
```

Then run `jac start` or `jac install --npm` to install them.

### Via CLI

```bash
# Add a runtime dependency
jac install --npm sonner

# Add a dev dependency
jac install --npm --dev tailwindcss

# Remove a dependency
jac remove --npm sonner
```

### What Packages Are Supported?

Any npm package that works with React and Vite is supported. This includes:

- **React ecosystem** -- React Router, React Query, Zustand, Jotai
- **UI component libraries** -- Radix UI, shadcn/ui, Material UI, Ant Design, Chakra UI
- **Styling** -- Tailwind CSS, Emotion, styled-components, CSS Modules
- **Utilities** -- lodash, date-fns, clsx, tailwind-merge, class-variance-authority
- **Editors** -- Monaco Editor, CodeMirror
- **Charts** -- Recharts, Chart.js, D3
- **Icons** -- HugeIcons, Lucide, React Icons, Heroicons
- **Terminals** -- xterm.js
- **Markdown** -- react-markdown, MDX

If a package works in a standard Vite + React project, it works in Jac.

### Basic Import Syntax

```jac
# Named imports
import from "sonner" { toast as sonnerToast }
import from "clsx" { clsx }
import from "tailwind-merge" { twMerge }

# Scoped packages
import from "@monaco-editor/react" { Editor, DiffEditor }
import from "@hugeicons/react" { HugeiconsIcon }
import from "@hugeicons/core-free-icons" { File02Icon, Cancel01Icon }

# Radix UI primitives
import from "radix-ui" { Dialog as DialogPrimitive }
import from "radix-ui" { Select as SelectPrimitive }
```

### Importing React Hooks Directly

While Jac provides idiomatic syntax for `useState` (`has`) and `useEffect` (`can with entry`), you can also import and use React hooks directly:

```jac
import from react { useState, useEffect, useRef, useCallback, useMemo }
```

- You need `useRef` for DOM element references or mutable values
- You need `useCallback` to memoize event handlers
- You need `useMemo` for expensive computations
- You prefer the explicit React API over Jac's sugar syntax

### useRef

`useRef` creates a mutable reference that persists across renders without triggering re-renders:

```jac
import from react { useRef }

def:pub TextInput() -> JsxElement {
    inputRef = useRef(None);

    def focusInput() -> None {
        if inputRef.current {
            inputRef.current.focus();
        }
    }

    return <div>
        <input ref={inputRef} type="text" />
        <button onClick={lambda -> None { focusInput(); }}>Focus</button>
    </div>;
}
```

!!! tip "Prefer the `Ref[T]` field form for component refs"

```jac
cl def:pub app -> JsxElement {
    has tasks: list = [],
        task_text: str = "",
        meal_text: str = "",
        ingredients: list = [],
        generating: bool = False;

    async can with entry {
        tasks = await get_tasks();
        ingredients = await get_shopping_list();
    }

    async def add_new_task {
        if task_text.strip() {
            task = await add_task(task_text.strip());
            tasks = tasks + [task];
            task_text = "";
        }
    }

    async def toggle(id: str) {
        updated = await toggle_task(id);
        tasks = [updated if jid(t) == id else t for t in tasks];
    }

    async def remove(id: str) {
        await delete_task(id);
        tasks = [t for t in tasks if jid(t) != id];
    }

    async def generate_meal_list {
        if meal_text.strip() {
            generating = True;
            ingredients = await generate_list(meal_text.strip());
            generating = False;
        }
    }

    async def clear_list {
        await clear_shopping_list();
        ingredients = [];
        meal_text = "";
    }

    remaining = len([t for t in tasks if not t.done]);
    total_cost = 0.0;
    for ing in ingredients { total_cost = total_cost + ing.cost; }

    return
        <div class="container">
            <h1>AI Day Planner</h1>
            <div class="two-column">
                <div class="column">
                    <h2>Today's Tasks</h2>
                    <div class="input-row">
                        <input
                            class="input"
                            value={task_text}
                            onChange={lambda (e: ChangeEvent) { task_text = e.target.value; }}
                            onKeyPress={lambda (e: KeyboardEvent) {
                                if e.key == "Enter" { add_new_task(); }
                            }}
                            placeholder="What needs to be done today?"
                        />
                        <button class="btn-add" onClick={add_new_task}>Add</button>
                    </div>
                    {[
                        <div key={jid(t)} class="task-item">
                            <input
                                type="checkbox"
                                checked={t.done}
                                onChange={lambda { toggle(jid(t)); }}
                            />
                            <span class={"task-title " + ("task-done" if t.done else "")}>
                                {t.title}
                            </span>
                            {(
                                <span class="category">{t.category}</span>
                            ) if t.category and t.category != "other" else None}
                            <button
                                class="btn-delete"
                                onClick={lambda { remove(jid(t)); }}
                            >
                                X
                            </button>
                        </div> for t in tasks
                    ]}
                    <div class="count">{remaining} {("task" if remaining == 1 else "tasks")} remaining</div>
                </div>
                <div class="column">
                    <h2>Meal Shopping List</h2>
                    <div class="input-row">
                        <input
                            class="input"
                            value={meal_text}
                            onChange={lambda (e: ChangeEvent) { meal_text = e.target.value; }}
                            onKeyPress={lambda (e: KeyboardEvent) {
                                if e.key == "Enter" { generate_meal_list(); }
                            }}
                            placeholder="Describe a meal, e.g. 'chicken stir fry for 4'"
                        />
                        <button
                            class="btn-generate"
                            onClick={generate_meal_list}
                            disabled={generating}
                        >
                            {("Generating..." if generating else "Generate")}
                        </button>
                    </div>
                    {(
                        <div class="generating-msg">Generating with AI...</div>
                    ) if generating else None}
                    {[
                        <div key={ing.name} class="ingredient-item">
                            <div class="ing-info">
                                <span class="ing-name">{ing.name}</span>
                                <span class="ing-qty">
                                    {ing.quantity} {ing.unit}
                                </span>
                            </div>
                            <div class="ing-meta">
                                {(
                                    <span class="carb-badge">Carbs</span>
                                ) if ing.carby else None}
                                <span class="ing-cost">${f"{ing.cost:.2f}"}</span>
