```jac
cl {
    def:pub Subscriber() -> JsxElement {
        has events: list = [];

        can with entry {
            subscribe_to_events();
        }

        # Cleanup on unmount
        can with exit {
            cleanup_subscriptions();
        }

        return <p>{len(events)} events</p>;
    }
}
```

!!! warning "Sharing a handle between setup and cleanup"
    `can with entry` and `can with exit` compile to *separate* `useEffect` closures, so a variable created in `entry` is not visible from `exit`. When setup produces a handle that cleanup needs -- an interval id, a subscription, an event listener -- do the setup and teardown in a **single** `useEffect` whose callback *returns* the cleanup function:

```jac
cl {
    import from react { useEffect }

    def:pub Timer() -> JsxElement {
        has seconds: int = 0;

        useEffect(lambda {
            intervalId = setInterval(lambda { seconds = seconds + 1; }, 1000);
            # The returned function is the cleanup -- it runs on unmount
            return lambda { clearInterval(intervalId); };
        }, []);

        return <p>Seconds: {seconds}</p>;
    }
}
```

### Manual useEffect

The `can with entry/exit` syntax above is the idiomatic approach and should be preferred. However, you can also use `useEffect` manually by importing from React -- this is useful for complex patterns involving `useRef` or `useCallback`:

```jac
cl {
    import from react { useEffect }

    def:pub DataFetcher() -> JsxElement {
        has data: list = [];

        useEffect(lambda -> None {
            fetch_data();
        }, []);

        return <div>...</div>;
    }
}
```

## Refs with `Ref[T]`

Just as `has` declares reactive state (`useState`) and `can with entry` declares effects (`useEffect`), a `has`-field typed `Ref[T]` declares a **ref** -- a mutable container that persists across renders but, unlike state, does **not** trigger a re-render when its `.current` changes. It compiles to React's `useRef`:

```jac
cl {
    def:pub FocusableInput() -> JsxElement {
        has inputRef: Ref[HTMLInputElement] = Ref();  # -> const inputRef = useRef(null)

        def focus() -> None {
            if inputRef.current { inputRef.current.focus(); }
        }

        return <div>
            <input ref={inputRef} type="text" />
            <button onClick={lambda -> None { focus(); }}>Focus</button>
        </div>;
    }
}
```

- `has r: Ref[T] = Ref()` compiles to `const r = useRef(null)` -- an empty DOM ref. Wire it to an element with `ref={r}`; React fills in `r.current` on mount.
- `has r: Ref[T] = Ref(initial)` compiles to `const r = useRef(initial)` -- a value ref seeded with `initial`, for mutable values that should survive re-renders without causing one.
- `useRef` is auto-imported from React; you do not import it yourself.

The field must be constructed (`= Ref()` / `= Ref(initial)`); a bare `has r: Ref[T];` is rejected ([E2025](../../reference/diagnostics.md)) because, like every other `has`-field, it needs a value. `.current` is typed `T | None`, so null-check it before use.

### Forwarding a ref into your component

The example above uses a ref *inside* a component. The other direction -- letting a **parent** attach a ref to a component *you* wrote -- requires the component to **forward** that ref to a real DOM node. A component opts in by declaring a trailing parameter typed `Ref`, a 1:1 match with React's `forwardRef((props, ref) => ...)` render signature:

```jac
cl {
    def:pub FancyInput(props: any, ref: Ref[HTMLInputElement]) -> JsxElement {
        return <input ref={ref} className="fancy" {**props} />;
    }
}
```

This lowers to `const FancyInput = forwardRef(function FancyInput(props, ref) { ... })`, so a parent can point its own ref at the component and reach the underlying `<input>`:

```jac
cl {
    def:pub ParentForm() -> JsxElement {
        has inputRef: Ref[HTMLInputElement] = Ref();
        return <FancyInput ref={inputRef} placeholder="Type here" />;
    }
}
```

- Only the **last** parameter qualifies, and it must be typed `Ref` (or `Ref[T]`). Named props before it destructure as usual; `ref` stays the trailing positional argument and is never folded into the props bundle.
- `forwardRef` is auto-imported from React; you do not import it yourself.
- A component that declares no `ref` parameter compiles exactly as before -- this is opt-in and zero-cost.

Forwarding is what makes a component usable as a [radix](npm-and-libraries.md) `asChild` trigger -- `DropdownMenuTrigger`, `Tooltip.Trigger`, `Popover.Trigger`, and friends attach a ref to their child to use as a positioning anchor, so a component that cannot forward a ref leaves that anchor null and the menu/popover silently never opens.

### Creating Context

```jac
cl {
    import from react { createContext, useContext }

    # Create context
    glob AppContext = createContext(None);

    # Provider component -- `children` is the nested JSX passed between its tags
    def:pub AppProvider(children: any = None) -> JsxElement {
        has user: any = None;
        has theme: str = "light";

        value = {
            "user": user,
            "theme": theme,
            "setUser": lambda (u: any) -> None { user = u; },
            "setTheme": lambda (t: str) -> None { theme = t; }
        };

        return <AppContext.Provider value={value}>
            {children}
        </AppContext.Provider>;
    }

    # Consumer component
    def:pub UserDisplay() -> JsxElement {
        ctx = useContext(AppContext);

        if ctx.user {
            return <p>Welcome, {ctx.user.name}!</p>;
        }
        return <p>Not logged in</p>;
    }

    def:pub ThemeToggle() -> JsxElement {
        ctx = useContext(AppContext);

        return <button onClick={lambda -> None {
            ctx.setTheme("dark" if ctx.theme == "light" else "light");
        }}>
            Toggle Theme ({ctx.theme})
        </button>;
    }

    def:pub app() -> JsxElement {
        return <AppProvider>
            <UserDisplay />
            <ThemeToggle />
        </AppProvider>;
    }
}
```

## Custom Hooks

Create reusable state logic:

```jac
cl {
    import from react { useEffect }

    # Custom hook
    def use_local_storage(key: str, initial_value: any) -> tuple {
        has value: any = initial_value;

        # Load from localStorage on mount
        useEffect(lambda -> None {
            stored = localStorage.getItem(key);
            if stored {
                value = JSON.parse(stored);
            }
        }, []);

        # Save to localStorage when value changes
        useEffect(lambda -> None {
            localStorage.setItem(key, JSON.stringify(value));
        }, [value]);

        return (value, lambda (v: any) -> None { value = v; });
    }

    def:pub Settings() -> JsxElement {
        (theme, set_theme) = use_local_storage("theme", "light");

        return <div>
            <p>Current theme: {theme}</p>
            <button onClick={lambda -> None { set_theme("dark"); }}>
                Dark
            </button>
            <button onClick={lambda -> None { set_theme("light"); }}>
                Light
            </button>
        </div>;
    }
}
```

### Loading State Pattern

```jac
cl {
    def:pub DataComponent() -> JsxElement {
        has data: any = None;
        has loading: bool = True;
        has error: str = "";

        # ... fetch data ...

        if loading {
            return <div className="spinner">Loading...</div>;
        }

        if error {
            return <div className="error">{error}</div>;
        }

        return <div>{data}</div>;
    }
}
```

### Form State Pattern

```jac
cl {
    def:pub ContactForm() -> JsxElement {
        has form_data: dict = {
            "name": "",
            "email": "",
            "message": ""
        };
        has errors: dict = {};
        has submitting: bool = False;

        def update_field(field: str, value: str) -> None {
            form_data = {**form_data, field: value};
        }

        def validate() -> bool {
            new_errors = {};
            if not form_data["name"] {
                new_errors["name"] = "Name is required";
            }
            if "@" not in form_data["email"] {
                new_errors["email"] = "Invalid email";
            }
            errors = new_errors;
            return len(new_errors) == 0;
        }

        def handle_submit() -> None {
            if validate() {
                submitting = True;
                # ... submit form ...
            }
        }

        return <form>
            <input
                value={form_data["name"]}
                onChange={lambda (e: ChangeEvent) { update_field("name", e.target.value); }}
            />
            {errors.get("name") and <span className="error">{errors["name"]}</span>}
        </form>;
    }
}
```

## Key Takeaways

| Concept | Jac Syntax | React Equivalent |
|---------|------------|------------------|
| State variable | `has count: int = 0` | `useState(0)` |
| Update state | `count = count + 1` | `setCount(count + 1)` |
| Effect on mount | `can with entry { ... }` | `useEffect(fn, [])` |
| Effect with deps | `can with [dep] entry { ... }` | `useEffect(fn, [dep])` |
| Cleanup on unmount | `can with exit { ... }` | `useEffect(() => cleanup, [])` |
| Global state | `useContext(Ctx)` | Same |<|im_end|>

## Overview

Jac compiles one source language to three first-class **codespaces** --
**`sv`** (server / Python), **`cl`** (client / JavaScript), and **`na`**
(native / LLVM) -- and a single `.jac` file may mix all three. Whenever a
call crosses from one codespace into another, or out to a foreign runtime
(CPython, C, or a WebAssembly host), the compiler has to *bridge* the gap:
discover the boundary, agree on a wire format, and synthesise the glue on
both sides.

This document is the reference for every one of those boundaries. It
assumes the codespace model from
[Compiler Architecture](compiler_architecture.md) -- read that first if the
terms `CodeContext`, `EsastGenPass`, `NaIRGenPass`, or "coercion" are new.
Here we go one level deeper: the *full* interop matrix, the mechanism behind
each cell, the marshalling format, and how desktop apps stitch several
boundaries into a single shippable binary.

### Two kinds of boundary

Every interop edge is one of two fundamentally different things:

- **Free boundaries** -- both sides live in the *same* runtime and address
  space, so a call is a direct function call and a value is passed by
  reference with no copy. Same-codespace calls (`sv→sv`, `cl→cl`, `na→na`)
  and Jac↔Python (`sv↔py`) are free.
- **Marshalled boundaries** -- the two sides are different runtimes
  (CPython ↔ V8, CPython ↔ machine code, machine code ↔ a wasm host). A call
  becomes an RPC or an FFI thunk, and every value that crosses must be
  *serialised* into a representation both sides understand. `cl↔sv`,
  `sv↔na`, `na↔C`, `na↔cl`, and the opt-in `sv→sv` microservice split are
  marshalled.

The compiler decides which is which automatically. Two analysis passes do
the discovery:

- **`BoundaryAnalysisPass`** detects an explicitly-tagged cross-runtime
  import (`sv import` inside a `.cl.jac`, a `clib` import in native code,
  etc.) and re-reads the *provider* module's AST to extract the public
  surface -- walker `has`-fields, `def` signatures, struct layouts -- into an
  `InteropBinding`.
- **`InteropAnalysisPass`** walks call sites, records the caller's and
  callee's `CodeContext` plus the boundary types, and accumulates them into
  an `InteropManifest`.

Both write their results into the schemas in
[`jac0core/codeinfo.jac`](https://github.com/Jaseci-Labs/jaseci/blob/main/jac/jaclang/jac0core/codeinfo.jac).
Each backend codegen pass then reads that manifest and emits *its half* of
every bridge it participates in. No global "target" flag exists -- selection
is per-node, driven entirely by each node's `code_context` tag.

## The full interop matrix

The three codespaces give nine ordered pairs; the three same-codespace
pairs are free, the six crossings are marshalled. Two external runtimes
(CPython for Python interop, and C / a wasm host for foreign FFI) add the
remaining rows.

| # | Direction | Boundary kind | Mechanism | What crosses | Synthesised by |
|---|-----------|---------------|-----------|--------------|----------------|
| 1 | **`sv → sv`** (in-process) | Free | Direct Python call | Live CPython objects (by ref) | -- (plain `import`) |
| 2 | **`sv → sv`** (microservice) | Marshalled | HTTP `POST` between deployments | JSON (`_to_wire`/`_from_wire`) | `PyastGenPass` (`sv import` stub) + `jaclang.scale` |
| 3 | **`cl → cl`** | Free | Direct JS call | JS values (by ref) | -- (`cl import`) |
| 4 | **`na → na`** | Free | Linker symbol reference | Native values / pointers | `NativeCompilePass` relocation |
| 5 | **`cl → sv`** | Marshalled | HTTP `POST /walker/*` or `/function/*` | JSON envelope | `EsastGenPass` (`__jacSpawn`/`__jacCallFunction`) + `jaclang.scale` |
| 6 | **`sv → cl`** | Marshalled (one-shot) | Static bundle + bootstrap JSON (CSR) | The compiled JS bundle + init payload | `PyastGenPass` static route + Vite/Bun bundler |
| 7 | **`sv → na`** | Marshalled | `ctypes.CFUNCTYPE` over the JIT address (or AOT `.so`) | C-ABI scalars; Jac objects as zero-copy views | `PyastGenPass` ctypes stub + `NaIRGenPass` C-ABI export |
| 8 | **`na → sv`** | Marshalled | Python callback registered as a JIT symbol | C-ABI scalars | `interop_bridge` (`llvm.add_symbol`) |
| 9 | **`cl → na`** | Marshalled | JS calls exported wasm functions | wasm scalars / linear memory | `wasm_build` + `WasmLinker` exports |
| 10 | **`na → cl`** | Marshalled | wasm imports the host `env` object | wasm scalars; host-provided externs | `WasmLinker` import table + cl host shim |
| 11 | **`sv/na ↔ py`** | Free | Literal Python import / meta-path finder | Live CPython objects | `PyastGenPass` (`import`→`ast.Import`) + `meta_importer` |
| 12 | **`na ↔ C`** | Marshalled (ABI) | System V AMD64 / AAPCS calling convention | C scalars & structs (by value or pointer) | `NaIRGenPass` clib marshaller |
| 13 | **`na → C host`** | Marshalled (ABI) | `--shared` C-ABI export | Scalars by value; Jac objects as opaque handles | `nacompile` `_inject_shared_init` + platform linkers |

## Free boundaries (rows 1, 3, 4, 11)

A free boundary is "interop" only in the bookkeeping sense -- there is no
wire format, no copy, and no generated glue. Two declarations in the *same*
codespace simply reference each other directly:

- **`sv → sv`** -- Jac server code is CPython bytecode. A `def` calling
  another `def` is an ordinary Python call; an `obj` handed to another
  function is the *same* object, not a copy. Plain (untagged) Jac `import`
  statements lower verbatim to Python `import` nodes (`exit_import` in
  [`pyast_gen_pass.impl.jac`](https://github.com/Jaseci-Labs/jaseci/blob/main/jac/jaclang/jac0core/passes/impl/pyast_gen_pass.impl.jac)),
  so resolution is the standard CPython import machinery.
- **`cl → cl`** -- Client code becomes one JavaScript module graph; a `cl`
  function calling another is a direct JS call, bundled together by Vite.
- **`na → na`** -- Two native modules link at the IR/object level. An import
  is a direct symbol reference resolved by the in-tree linker
  (`_compile_and_link_native_imports` in `NativeCompilePass`). The linker
  rejects duplicate *owned* symbols with `E5026`.
- **`sv ↔ py`** -- Because `sv` *is* the Python target, server code and
  imported Python share one interpreter, one `sys.modules`, and one object
  model. This is covered in full under [Python interop](#python-interop-row-11)
  below.

> The single most important consequence: **values only need a wire format
> when they cross a marshalled boundary.** Inside one codespace (or between
> `sv` and Python) you pass live objects around for free.

## `cl → sv`: the full-stack RPC (row 5)

This is the boundary that makes a Jac app full-stack: client-side
JavaScript calling server-side walkers

- **React ecosystem** -- React Router, React Query, Zustand, Jotai
- **UI component libraries** -- Radix UI, shadcn/ui, Material UI, Ant Design, Chakra UI
- **Styling** -- Tailwind CSS, Emotion, styled-components, CSS Modules
- **Utilities** -- lodash, date-fns, clsx, tailwind-merge, class-variance-authority
- **Editors** -- Monaco Editor, CodeMirror
- **Charts** -- Recharts, Chart.js, D3
- **Icons** -- HugeIcons, Lucide, React Icons, Heroicons
- **Terminals** -- xterm.js
- **Markdown** -- react-markdown, MDX

If a package works in a standard Vite + React project, it works in Jac.

### Basic Import Syntax

```jac
# Named imports
import from "sonner" { toast as sonnerToast }
import from "clsx" { clsx }
import from "tailwind-merge" { twMerge }

# Scoped packages
import from "@monaco-editor/react" { Editor, DiffEditor }
import from "@hugeicons/react" { HugeiconsIcon }
import from "@hugeicons/core-free-icons" { File02Icon, Cancel01Icon }

# Radix UI primitives
import from "radix-ui" { Dialog as DialogPrimitive }
import from "radix-ui" { Select as SelectPrimitive }
```

### Importing React Hooks Directly

While Jac provides idiomatic syntax for `useState` (`has`) and `useEffect` (`can with entry`), you can also import and use React hooks directly:

```jac
import from react { useState, useEffect, useRef, useCallback, useMemo }
```

- You need `useRef` for DOM element references or mutable values
- You need `useCallback` to memoize event handlers
- You need `useMemo` for expensive computations
- You prefer the explicit React API over Jac's sugar syntax

### useRef

`useRef` creates a mutable reference that persists across renders without triggering re-renders:

```jac
import from react { useRef }

def:pub TextInput() -> JsxElement {
    inputRef = useRef(None);

    def focusInput() -> None {
        if inputRef.current {
            inputRef.current.focus();
        }
    }

    return <div>
        <input ref={inputRef} type="text" />
        <button onClick={lambda -> None { focusInput(); }}>Focus</button>
    </div>;
}
```

!!! tip "Prefer the `Ref[T]` field form for component refs"
    For a ref you hold for the life of a component, declare it as a typed
    `has`-field instead of a manual import: `has inputRef: Ref[HTMLInputElement] = Ref();`
    compiles to the same `useRef(null)`, auto-imports `useRef`, and gives
    `.current` a real type (`HTMLInputElement | None`). See
    [Refs with `Ref[T]`](state.md). The manual `import from react { useRef }`
    form shown here is still useful for inline locals and value refs created
    mid-function.

<!-- jac-skip -->
```jac
# DOM element reference
scrollRef = useRef(None);

# Mutable value that doesn't trigger re-render
timerRef = useRef(None);
prevValueRef = useRef("");

# Track a state value without re-rendering
isMountedRef = useRef(False);
```

### useCallback

`useCallback` memoizes a function so it only changes when dependencies change:

```jac
import from react { useCallback }

def:pub FileUploader() -> JsxElement {
    fileInputRef = useRef(None);

    triggerPicker = useCallback(lambda -> None {
        if fileInputRef.current {
            fileInputRef.current.click();
        }
    }, []);

    return <div>
        <input ref={fileInputRef} type="file" style={{"display": "none"}} />
        <button onClick={triggerPicker}>Upload File</button>
    </div>;
}
```

### Mixing Jac Sugar with Direct React Hooks

You can freely mix `has` (useState sugar) with direct React hook imports in the same component:

```jac
import from react { useRef, useCallback, useEffect }

def:pub SearchBox() -> JsxElement {
    has query: str = "";           # Jac sugar for useState
    has results: list = [];        # Jac sugar for useState
    inputRef = useRef(None);       # Direct React hook

    # Jac sugar for useEffect with dependency
    async can with [query] entry {
        if query {
            results = await search_api(query);
        }
    }

    # Direct React useEffect for DOM manipulation
    useEffect(lambda -> None {
        if inputRef.current {
            inputRef.current.focus();
        }
    }, []);

    return <div>
        <input
            ref={inputRef}
            value={query}
            onChange={lambda (e: ChangeEvent) { query = e.target.value; }}
        />
        <ul>{[<li key={r.id}>{r.title}</li> for r in results]}</ul>
    </div>;
}
```

