        x = 10;
        y = 3;
        print(f"{x} + {y} = {x + y}");
        print(f"{x} ** {y} = {x ** y}");
        print(f"{x} > {y} = {x > y}");
        print(f"not False = {not False}");
        print(f"{x} in [1,5,10] = {x in [1, 5, 10]}");
