### Custom Protected Routes

```jac
cl import from "@jac/runtime" { useNavigate, jacIsLoggedIn }

cl {
    def:pub ProtectedRoute(children: any = None) -> JsxElement {
        navigate = useNavigate();
        isAuthenticated = jacIsLoggedIn();

