        ret_str = False

        if o is None:
            o = StringIO()
            ret_str = True
        rlen = len(self._reg.register_name) + 2
        o.write(".. _%s:\n\n" % self.refname(self._reg.register_name))
        o.write(self._reg.register_name)
        o.write("\n%s\n\n" % ('_' * rlen))

        if ret_str:
