    def str_bit_fields(self, o=None):
        ret_str = False

        if o is None:
            o = StringIO()
            ret_str = True
        o.write(".. role:: resetvalue\n\n")
        o.write(".. role:: editable\n\n")
        o.write(".. role:: mono\n\n")
        o.write(".. list-table::\n")
        o.write("   :name: bit_table\n")
        o.write("   :widths: 8, 10, 7, 25, 50\n")
        if self._bootstrap:
