            elif len(addr_maps) == 2:
                o.write("   :widths: 50, 25, 25\n")
            elif len(addr_maps) == 3:
                o.write("   :widths: 50, 16, 16, 17\n")
            if self._bootstrap:
                o.write("   :class: table table-bordered table-striped table-condensed\n\n")
            else:
                o.write("   :class: summary\n\n")
            o.write("   *")
            if use_uvm:
