    """Tasks column -- owns task list state, spawns walkers for CRUD."""

    sv import from ..main { Task, AddTask, ListTasks, ToggleTask, DeleteTask }

    import from .TaskItem { TaskItem }

    def:pub TasksPanel -> JsxElement {
        has tasks: list[Task] = [],
            taskText: str = "",
