#*********** checkId ***************
def __checkId(self, id) :
	return id in self.__serverList
#*********** end checkId ***********

#*********** nrOfActiveServers ***************
def __nrOfActiveServers(self) :
	i=0
	for s in self.__serverList:
		if self.__serverList[s].isActive:
			i+=1
	return i
#*********** end __nrOfActiveServers ***********


